//! Reference chart datasets for both ColorChecker Classic revisions.
//!
//! The reference values are committed in `data/chart-datasets.json`
//! (generated by `research/generate_reference_data.py` with colour-science
//! 0.4.4) and are never computed at runtime. [`load`] parses and validates
//! the embedded bytes and returns the 24 [`PatchReference`] entries of the
//! requested revision in [`crate::chart::ChartModel`] reading order.
//!
//! Revision keys and patch `name` strings in the JSON separate digit runs
//! with hyphens (`"classic-before-november-2014"`, `"neutral-6-5"`), while
//! serde's `kebab-case` rename never inserts a separator before a digit
//! (`"classic-before-november2014"`, `"neutral65"`). The names are therefore
//! mapped explicitly instead of deserializing the enums directly.

use crate::chart::{ChartModel, ChartPatch, ChartRevision};
use serde::Deserialize;
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;

/// The committed reference datasets, embedded at compile time.
const DATASET_JSON: &str = include_str!("../data/chart-datasets.json");

/// Number of patches on a ColorChecker Classic chart.
const PATCH_COUNT: usize = 24;

/// Illuminant the reference XYZ values are tabulated for.
const EXPECTED_ILLUMINANT: &str = "D50";
/// Observer the reference values are tabulated for.
const EXPECTED_OBSERVER: &str = "CIE 1931 2 Degree Standard Observer";
/// Chromatic adaptation transform used to derive the D65 tables.
const EXPECTED_ADAPTATION: &str = "Bradford";
/// White point the sRGB and Lab tables are adapted to.
const EXPECTED_TARGET_WHITE_POINT: &str = "D65";

/// Reference values for one chart patch.
#[derive(Debug, Clone, PartialEq)]
pub struct PatchReference {
    /// The patch these values describe.
    pub patch: ChartPatch,
    /// CIE 1931 chromaticity `x, y` plus luminance `Y`.
    pub xy_y: [f64; 3],
    /// Tristimulus values under D50.
    pub xyz_d50: [f64; 3],
    /// Tristimulus values under D65 (Bradford adapted from D50).
    pub xyz_d65: [f64; 3],
    /// Linear sRGB primaries under D65; the cyan patch is slightly out of
    /// the sRGB gamut and therefore carries a small negative component.
    pub linear_srgb_d65: [f64; 3],
    /// CIELAB `L*, a*, b*` under D65.
    pub lab_d65: [f64; 3],
}

/// A validated reference dataset for one chart revision.
#[derive(Debug, Clone, PartialEq)]
pub struct ChartDataset {
    /// The revision the patches belong to.
    pub revision: ChartRevision,
    /// Provenance string from the dataset file.
    pub source: String,
    /// Illuminant the reference values are tabulated for (`"D50"`).
    pub illuminant: String,
    /// Observer the reference values are tabulated for.
    pub observer: String,
    /// Chromatic adaptation used to derive the D65 tables (`"Bradford"`).
    pub adaptation: String,
    /// All 24 patches in reading order.
    pub patches: Vec<PatchReference>,
}

/// Failures produced while loading a reference dataset.
#[derive(Debug, thiserror::Error)]
pub enum DatasetError {
    /// The dataset exists but violates the contract (patch count, patch
    /// order, illuminant, observer, adaptation, or value sanity).
    #[error("invalid dataset: {0}")]
    InvalidDataset(String),
    /// The JSON carries a revision string that is not a known chart
    /// revision.
    #[error("unknown chart revision string \"{0}\"")]
    UnknownRevision(String),
    /// The bytes are not the expected JSON shape.
    #[error("dataset parse failed: {0}")]
    Parse(#[from] serde_json::Error),
}

/// JSON object as committed in the dataset file.
#[derive(Debug, Deserialize)]
struct RawDataset {
    source: String,
    illuminant: String,
    observer: String,
    adaptation: String,
    #[serde(rename = "targetWhitePoint")]
    target_white_point: String,
    patches: Vec<RawPatch>,
}

/// One patch entry as committed in the dataset file.
#[derive(Debug, Deserialize)]
struct RawPatch {
    /// Patch name; validated against [`patch_name`] reading order.
    name: String,
    /// Human-readable patch label from the spectral dataset.
    #[serde(rename = "sdName")]
    sd_name: String,
    #[serde(rename = "xyY")]
    xy_y: [f64; 3],
    #[serde(rename = "xyzD50")]
    xyz_d50: [f64; 3],
    #[serde(rename = "xyzD65")]
    xyz_d65: [f64; 3],
    #[serde(rename = "linearSrgbD65")]
    linear_srgb_d65: [f64; 3],
    #[serde(rename = "labD65")]
    lab_d65: [f64; 3],
}

/// Committed JSON key for a revision.
fn revision_key(revision: ChartRevision) -> &'static str {
    match revision {
        ChartRevision::ClassicBeforeNovember2014 => "classic-before-november-2014",
        ChartRevision::ClassicFromNovember2014 => "classic-from-november-2014",
    }
}

/// Parse a committed revision key back into a [`ChartRevision`].
fn revision_from_key(key: &str) -> Option<ChartRevision> {
    match key {
        "classic-before-november-2014" => Some(ChartRevision::ClassicBeforeNovember2014),
        "classic-from-november-2014" => Some(ChartRevision::ClassicFromNovember2014),
        _ => None,
    }
}

/// Committed JSON patch name for a patch.
fn patch_name(patch: ChartPatch) -> &'static str {
    match patch {
        ChartPatch::DarkSkin => "dark-skin",
        ChartPatch::LightSkin => "light-skin",
        ChartPatch::BlueSky => "blue-sky",
        ChartPatch::Foliage => "foliage",
        ChartPatch::BlueFlower => "blue-flower",
        ChartPatch::BluishGreen => "bluish-green",
        ChartPatch::Orange => "orange",
        ChartPatch::PurplishBlue => "purplish-blue",
        ChartPatch::ModerateRed => "moderate-red",
        ChartPatch::Purple => "purple",
        ChartPatch::YellowGreen => "yellow-green",
        ChartPatch::OrangeYellow => "orange-yellow",
        ChartPatch::Blue => "blue",
        ChartPatch::Green => "green",
        ChartPatch::Red => "red",
        ChartPatch::Yellow => "yellow",
        ChartPatch::Magenta => "magenta",
        ChartPatch::Cyan => "cyan",
        ChartPatch::White => "white",
        ChartPatch::Neutral8 => "neutral-8",
        ChartPatch::Neutral65 => "neutral-6-5",
        ChartPatch::Neutral5 => "neutral-5",
        ChartPatch::Neutral35 => "neutral-3-5",
        ChartPatch::Black => "black",
    }
}

/// Load the committed reference dataset for a revision.
///
/// # Errors
///
/// Returns a [`DatasetError`] if the embedded JSON cannot be parsed or
/// violates the dataset contract (24 patches in [`ChartModel`] reading
/// order, D50 illuminant, CIE 1931 2 Degree Standard Observer, Bradford
/// adaptation, D65 target white point, finite values).
pub fn load(revision: ChartRevision) -> Result<ChartDataset, DatasetError> {
    load_from_str(DATASET_JSON, revision)
}

/// Parse and validate a dataset JSON document for one revision.
///
/// Same contract as [`load`], but over caller-provided bytes; it exists so
/// tests can feed tampered documents. Production code must use [`load`].
///
/// # Errors
///
/// Returns a [`DatasetError`] when the document is not valid dataset JSON
/// or fails validation for the requested revision.
pub fn load_from_str(json: &str, revision: ChartRevision) -> Result<ChartDataset, DatasetError> {
    let raw: BTreeMap<String, RawDataset> = serde_json::from_str(json)?;
    for key in raw.keys() {
        if revision_from_key(key).is_none() {
            return Err(DatasetError::UnknownRevision(key.clone()));
        }
    }
    let key = revision_key(revision);
    let dataset = raw.get(key).ok_or_else(|| {
        DatasetError::InvalidDataset(format!("dataset for revision \"{key}\" is missing"))
    })?;
    validate_dataset(key, revision, dataset)
}

/// Validate one parsed dataset and convert it to the public shape.
fn validate_dataset(
    key: &str,
    revision: ChartRevision,
    dataset: &RawDataset,
) -> Result<ChartDataset, DatasetError> {
    if dataset.illuminant != EXPECTED_ILLUMINANT {
        return Err(DatasetError::InvalidDataset(format!(
            "revision \"{key}\" illuminant must be \"{EXPECTED_ILLUMINANT}\", found \"{}\"",
            dataset.illuminant
        )));
    }
    if dataset.observer != EXPECTED_OBSERVER {
        return Err(DatasetError::InvalidDataset(format!(
            "revision \"{key}\" observer must be \"{EXPECTED_OBSERVER}\", found \"{}\"",
            dataset.observer
        )));
    }
    if dataset.adaptation != EXPECTED_ADAPTATION {
        return Err(DatasetError::InvalidDataset(format!(
            "revision \"{key}\" adaptation must be \"{EXPECTED_ADAPTATION}\", found \"{}\"",
            dataset.adaptation
        )));
    }
    if dataset.target_white_point != EXPECTED_TARGET_WHITE_POINT {
        return Err(DatasetError::InvalidDataset(format!(
            "revision \"{key}\" targetWhitePoint must be \"{EXPECTED_TARGET_WHITE_POINT}\", found \"{}\"",
            dataset.target_white_point
        )));
    }
    if dataset.patches.len() != PATCH_COUNT {
        return Err(DatasetError::InvalidDataset(format!(
            "revision \"{key}\" must list {PATCH_COUNT} patches, found {}",
            dataset.patches.len()
        )));
    }
    let model = ChartModel::new(revision);
    let mut patches = Vec::with_capacity(PATCH_COUNT);
    for (index, patch) in dataset.patches.iter().enumerate() {
        let expected = patch_name(model.patches[index]);
        if patch.name != expected {
            return Err(DatasetError::InvalidDataset(format!(
                "revision \"{key}\" patch {index} must be \"{expected}\", found \"{}\"",
                patch.name
            )));
        }
        if patch.sd_name.trim().is_empty() {
            return Err(DatasetError::InvalidDataset(format!(
                "revision \"{key}\" patch {index} (\"{}\") has an empty sdName",
                patch.name
            )));
        }
        let values = [
            ("xyY", patch.xy_y),
            ("xyzD50", patch.xyz_d50),
            ("xyzD65", patch.xyz_d65),
            ("linearSrgbD65", patch.linear_srgb_d65),
            ("labD65", patch.lab_d65),
        ];
        for (field, components) in values {
            if !components.iter().all(|c| c.is_finite()) {
                return Err(DatasetError::InvalidDataset(format!(
                    "revision \"{key}\" patch {index} (\"{}\") field {field} has a non-finite value",
                    patch.name
                )));
            }
        }
        patches.push(PatchReference {
            patch: model.patches[index],
            xy_y: patch.xy_y,
            xyz_d50: patch.xyz_d50,
            xyz_d65: patch.xyz_d65,
            linear_srgb_d65: patch.linear_srgb_d65,
            lab_d65: patch.lab_d65,
        });
    }
    Ok(ChartDataset {
        revision,
        source: dataset.source.clone(),
        illuminant: dataset.illuminant.clone(),
        observer: dataset.observer.clone(),
        adaptation: dataset.adaptation.clone(),
        patches,
    })
}

/// SHA-256 of the embedded dataset JSON bytes, as lowercase hex.
///
/// The digest identifies the reference data a profile was derived against;
/// it is stable as long as `data/chart-datasets.json` is unchanged.
pub fn dataset_digest() -> String {
    let digest = Sha256::digest(DATASET_JSON.as_bytes());
    let mut hex = String::with_capacity(digest.len() * 2);
    for byte in digest {
        use std::fmt::Write as _;
        let _ = write!(hex, "{byte:02x}");
    }
    hex
}

#[cfg(test)]
mod tests {
    use super::*;

    /// SHA-256 over the committed `data/chart-datasets.json` bytes.
    const COMMITTED_DIGEST: &str =
        "ec2f973e9e70e8acb2054264359053ee2d2ebcac1d5086848cf284dbd7539edb";
    const KEY_BEFORE: &str = "classic-before-november-2014";

    const REVISIONS: [ChartRevision; 2] = [
        ChartRevision::ClassicBeforeNovember2014,
        ChartRevision::ClassicFromNovember2014,
    ];

    /// dark-skin `xyY` straight from the committed JSON, per revision.
    const DARK_SKIN_XY_Y_BEFORE: [f64; 3] = [0.4316271709, 0.3777244481, 0.1008020776];
    const DARK_SKIN_XY_Y_FROM: [f64; 3] = [0.4374835978, 0.3785228425, 0.098324361];
    /// White patch `linearSrgbD65` per revision.
    const WHITE_LINEAR_BEFORE: [f64; 3] = [0.9123003489, 0.915109206, 0.8934741519];
    const WHITE_LINEAR_FROM: [f64; 3] = [0.8793522329, 0.8851042499, 0.8340000421];
    /// Black patch `linearSrgbD65` per revision.
    const BLACK_LINEAR_BEFORE: [f64; 3] = [0.030308393, 0.0311438493, 0.032741199];
    const BLACK_LINEAR_FROM: [f64; 3] = [0.0313479734, 0.0314986017, 0.0323130917];

    /// Re-serialize the embedded JSON after applying an edit.
    fn tampered(edit: impl FnOnce(&mut serde_json::Value)) -> String {
        let mut root: serde_json::Value =
            serde_json::from_str(DATASET_JSON).expect("embedded dataset JSON parses");
        edit(&mut root);
        root.to_string()
    }

    #[test]
    fn both_revisions_load_in_chart_model_order() {
        for revision in REVISIONS {
            let dataset = load(revision).expect("embedded dataset loads");
            assert_eq!(dataset.revision, revision);
            assert_eq!(dataset.illuminant, "D50");
            assert_eq!(dataset.observer, "CIE 1931 2 Degree Standard Observer");
            assert_eq!(dataset.adaptation, "Bradford");
            let model = ChartModel::new(revision);
            assert_eq!(dataset.patches.len(), 24);
            for (index, reference) in dataset.patches.iter().enumerate() {
                assert_eq!(reference.patch, model.patches[index], "patch {index}");
            }
        }
        assert_eq!(
            load(ChartRevision::ClassicBeforeNovember2014)
                .expect("before-2014 loads")
                .source,
            "ColorChecker24 - Before November 2014"
        );
        assert_eq!(
            load(ChartRevision::ClassicFromNovember2014)
                .expect("from-2014 loads")
                .source,
            "ColorChecker24 - After November 2014"
        );
    }

    #[test]
    fn reference_values_match_committed_json() {
        let before = load(ChartRevision::ClassicBeforeNovember2014).expect("before-2014 loads");
        let from = load(ChartRevision::ClassicFromNovember2014).expect("from-2014 loads");
        assert_eq!(before.patches[0].patch, ChartPatch::DarkSkin);
        assert_eq!(before.patches[0].xy_y, DARK_SKIN_XY_Y_BEFORE);
        assert_eq!(from.patches[0].xy_y, DARK_SKIN_XY_Y_FROM);
        assert_eq!(before.patches[18].linear_srgb_d65, WHITE_LINEAR_BEFORE);
        assert_eq!(from.patches[18].linear_srgb_d65, WHITE_LINEAR_FROM);
        assert_eq!(before.patches[23].linear_srgb_d65, BLACK_LINEAR_BEFORE);
        assert_eq!(from.patches[23].linear_srgb_d65, BLACK_LINEAR_FROM);
        // The revisions must genuinely differ, not alias one table.
        assert_ne!(before.patches[0].xyz_d50, from.patches[0].xyz_d50);
    }

    #[test]
    fn load_from_str_rejects_wrong_patch_order() {
        let json = tampered(|root| {
            let patches = root[KEY_BEFORE]["patches"]
                .as_array_mut()
                .expect("patches array");
            patches.swap(0, 1);
        });
        let error = load_from_str(&json, ChartRevision::ClassicBeforeNovember2014)
            .expect_err("swapped patch order must be rejected");
        assert_eq!(
            error.to_string(),
            "invalid dataset: revision \"classic-before-november-2014\" \
             patch 0 must be \"dark-skin\", found \"light-skin\""
        );
    }

    #[test]
    fn load_from_str_rejects_wrong_patch_count() {
        let json = tampered(|root| {
            let patches = root[KEY_BEFORE]["patches"]
                .as_array_mut()
                .expect("patches array");
            patches.pop();
        });
        let error = load_from_str(&json, ChartRevision::ClassicBeforeNovember2014)
            .expect_err("23 patches must be rejected");
        assert_eq!(
            error.to_string(),
            "invalid dataset: revision \"classic-before-november-2014\" \
             must list 24 patches, found 23"
        );
    }

    #[test]
    fn load_from_str_rejects_unknown_revision() {
        let json = tampered(|root| {
            let entry = root.as_object_mut().expect("dataset root object");
            let value = entry.remove(KEY_BEFORE).expect("revision entry");
            entry.insert("classic-spring-2016".to_string(), value);
        });
        let error = load_from_str(&json, ChartRevision::ClassicBeforeNovember2014)
            .expect_err("unknown revision key must be rejected");
        assert_eq!(
            error.to_string(),
            "unknown chart revision string \"classic-spring-2016\""
        );
        assert!(matches!(error, DatasetError::UnknownRevision(_)));
    }

    #[test]
    fn load_from_str_rejects_missing_revision() {
        let json = tampered(|root| {
            root.as_object_mut()
                .expect("dataset root object")
                .remove(KEY_BEFORE);
        });
        let error = load_from_str(&json, ChartRevision::ClassicBeforeNovember2014)
            .expect_err("missing revision must be rejected");
        assert_eq!(
            error.to_string(),
            "invalid dataset: dataset for revision \"classic-before-november-2014\" is missing"
        );
    }

    #[test]
    fn load_from_str_rejects_wrong_dataset_strings() {
        for (field, value, expected) in [
            (
                "illuminant",
                "D65",
                "invalid dataset: revision \"classic-before-november-2014\" \
                 illuminant must be \"D50\", found \"D65\"",
            ),
            (
                "observer",
                "CIE 1964 10 Degree Standard Observer",
                "invalid dataset: revision \"classic-before-november-2014\" \
                 observer must be \"CIE 1931 2 Degree Standard Observer\", \
                 found \"CIE 1964 10 Degree Standard Observer\"",
            ),
            (
                "adaptation",
                "Von Kries",
                "invalid dataset: revision \"classic-before-november-2014\" \
                 adaptation must be \"Bradford\", found \"Von Kries\"",
            ),
        ] {
            let json = tampered(|root| {
                root[KEY_BEFORE][field] = serde_json::Value::String(value.to_string());
            });
            let error = load_from_str(&json, ChartRevision::ClassicBeforeNovember2014).unwrap_err();
            assert_eq!(error.to_string(), expected, "tampered {field}");
        }
    }

    #[test]
    fn load_from_str_rejects_malformed_json() {
        let error = load_from_str("{ not json", ChartRevision::ClassicBeforeNovember2014)
            .expect_err("malformed JSON must be rejected");
        assert!(matches!(error, DatasetError::Parse(_)));
    }

    #[test]
    fn digest_is_64_lowercase_hex_and_stable() {
        let digest = dataset_digest();
        assert_eq!(digest.len(), 64);
        assert!(
            digest
                .bytes()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)),
            "digest must be lowercase hex, found {digest}"
        );
        assert_eq!(digest, dataset_digest());
        assert_eq!(digest, COMMITTED_DIGEST);
    }

    #[test]
    fn linear_srgb_values_are_sane() {
        // The cyan patch lies slightly outside the sRGB gamut, so its
        // linear sRGB components dip below zero by less than 0.05; every
        // other component is a plain reflectance scale in [0, 2].
        for revision in REVISIONS {
            let dataset = load(revision).expect("embedded dataset loads");
            for reference in &dataset.patches {
                for component in reference.linear_srgb_d65 {
                    assert!(
                        (-0.05..=2.0).contains(&component),
                        "{} linearSrgbD65 component {component} out of range",
                        patch_name(reference.patch)
                    );
                }
            }
        }
    }

    #[test]
    fn neutral_row_luminance_strictly_decreases_white_to_black() {
        let order = [
            ChartPatch::White,
            ChartPatch::Neutral8,
            ChartPatch::Neutral65,
            ChartPatch::Neutral5,
            ChartPatch::Neutral35,
            ChartPatch::Black,
        ];
        for revision in REVISIONS {
            let dataset = load(revision).expect("embedded dataset loads");
            let model = ChartModel::new(revision);
            let luminance: Vec<f64> = order
                .iter()
                .map(|patch| {
                    let index = model.index_of(*patch).expect("patch exists");
                    dataset.patches[index].linear_srgb_d65[1]
                })
                .collect();
            assert!(
                luminance.windows(2).all(|pair| pair[0] > pair[1]),
                "neutral luminance must strictly decrease, got {luminance:?}"
            );
        }
        // Luminance is read from the committed table, never recomputed.
        assert_eq!(
            load(ChartRevision::ClassicBeforeNovember2014)
                .expect("before-2014 loads")
                .patches[18]
                .linear_srgb_d65[1],
            WHITE_LINEAR_BEFORE[1]
        );
        assert_eq!(
            load(ChartRevision::ClassicFromNovember2014)
                .expect("from-2014 loads")
                .patches[18]
                .linear_srgb_d65[1],
            WHITE_LINEAR_FROM[1]
        );
    }
}
